    const jsonData = pm.response.json();
    pm.expect(jsonData).to.be.an("array");
});

pm.test("Staff training record exists", function () {
    const jsonData = pm.response.json();

    const found = jsonData.some(document => {
        const fileName =
            document.name ??
            document.fileName ??
            document.Name ??
            document.FileName;

        return fileName === "Staff_Training.txt";
    });

    pm.expect(found).to.be.true;
});

pm.test("Document downloaded successfully", function () {
    pm.response.to.have.status(200);
});

